import './styles.css';
import { useState } from 'react';

interface Dimension {
  id: string;
  name: string;
  icon: string;
  color: string;
  criteria: Criterion[];
}

interface Criterion {
  id: string;
  statement: string;
  levels: {
    low: string;
    medium: string;
    high: string;
  };
}

const dimensions: Dimension[] = [
  {
    id: 'goals',
    name: 'Clear Goals',
    icon: '🎯',
    color: '#3b82f6',
    criteria: [
      {
        id: 'goals-1',
        statement: 'We have a specific business problem AI would solve',
        levels: {
          low: 'Vague: "We want to use AI"',
          medium: 'Directional: "Improve customer service"',
          high: 'Specific: "Reduce response time by 40%"'
        }
      },
      {
        id: 'goals-2',
        statement: 'We can measure whether AI is working',
        levels: {
          low: 'No clear metrics defined',
          medium: 'Some KPIs, not all tracked',
          high: 'Clear baselines and targets set'
        }
      }
    ]
  },
  {
    id: 'data',
    name: 'Quality Data',
    icon: '📊',
    color: '#8b5cf6',
    criteria: [
      {
        id: 'data-1',
        statement: 'Our data is organized and accessible',
        levels: {
          low: 'Scattered across systems, inconsistent',
          medium: 'Mostly centralized, some gaps',
          high: 'Clean, structured, documented'
        }
      },
      {
        id: 'data-2',
        statement: 'We have enough relevant data for training',
        levels: {
          low: 'Very limited historical data',
          medium: 'Reasonable data, some gaps',
          high: 'Rich dataset covering key scenarios'
        }
      }
    ]
  },
  {
    id: 'culture',
    name: 'Culture Change',
    icon: '🌱',
    color: '#10b981',
    criteria: [
      {
        id: 'culture-1',
        statement: 'Staff are open to working with AI tools',
        levels: {
          low: 'Skeptical or fearful of AI',
          medium: 'Curious but uncertain',
          high: 'Enthusiastic, see AI as a help'
        }
      },
      {
        id: 'culture-2',
        statement: 'Leadership supports and resources AI initiatives',
        levels: {
          low: 'No clear sponsor or budget',
          medium: 'Some support, competing priorities',
          high: 'Executive champion with budget'
        }
      }
    ]
  },
  {
    id: 'capacity',
    name: 'Capacity',
    icon: '🛠️',
    color: '#f59e0b',
    criteria: [
      {
        id: 'capacity-1',
        statement: 'We have people who can implement and maintain AI',
        levels: {
          low: 'No technical expertise',
          medium: 'Some skills, would need training',
          high: 'Skilled team or strong vendor partner'
        }
      },
      {
        id: 'capacity-2',
        statement: 'We can sustain this beyond the initial project',
        levels: {
          low: 'One-time budget only',
          medium: 'Some ongoing funds unclear',
          high: 'Long-term budget and ownership'
        }
      }
    ]
  },
  {
    id: 'expectations',
    name: 'Realistic Expectations',
    icon: '⚖️',
    color: '#ec4899',
    criteria: [
      {
        id: 'expect-1',
        statement: 'We understand AI will augment, not replace, human work',
        levels: {
          low: 'Expecting full automation',
          medium: 'Know humans needed, unclear how',
          high: 'Clear human-AI workflow designed'
        }
      },
      {
        id: 'expect-2',
        statement: 'We\'re starting with a focused pilot, not transforming everything',
        levels: {
          low: 'Want to AI-enable everything at once',
          medium: 'Have a focus area, scope unclear',
          high: 'Specific pilot with success criteria'
        }
      }
    ]
  }
];

type Level = 'low' | 'medium' | 'high' | null;

function DimensionCard({
  dimension,
  scores,
  onScore,
  isExpanded,
  onToggle
}: {
  dimension: Dimension;
  scores: Record<string, Level>;
  onScore: (criterionId: string, level: Level) => void;
  isExpanded: boolean;
  onToggle: () => void;
}) {
  const answered = dimension.criteria.filter(c => scores[c.id] !== null).length;
  const avgScore = dimension.criteria.reduce((sum, c) => {
    const s = scores[c.id];
    if (s === 'high') return sum + 3;
    if (s === 'medium') return sum + 2;
    if (s === 'low') return sum + 1;
    return sum;
  }, 0) / (answered || 1);

  return (
    <div className={`dimension-card ${isExpanded ? 'expanded' : ''}`} style={{ borderColor: dimension.color }}>
      <div className="dim-header" onClick={onToggle}>
        <div className="dim-title">
          <span className="dim-icon">{dimension.icon}</span>
          <h3>{dimension.name}</h3>
        </div>
        <div className="dim-meta">
          {answered === dimension.criteria.length && (
            <span className="avg-badge" style={{ 
              backgroundColor: avgScore >= 2.5 ? '#d1fae5' : avgScore >= 1.5 ? '#fef3c7' : '#fee2e2',
              color: avgScore >= 2.5 ? '#059669' : avgScore >= 1.5 ? '#b45309' : '#dc2626'
            }}>
              {avgScore >= 2.5 ? 'Ready' : avgScore >= 1.5 ? 'Building' : 'Gap'}
            </span>
          )}
          <span className="progress-text">{answered}/{dimension.criteria.length}</span>
          <span className="toggle-icon">{isExpanded ? '−' : '+'}</span>
        </div>
      </div>

      {isExpanded && (
        <div className="dim-body">
          {dimension.criteria.map(criterion => (
            <div key={criterion.id} className="criterion">
              <p className="criterion-statement">{criterion.statement}</p>
              <div className="level-options">
                {(['low', 'medium', 'high'] as const).map(level => (
                  <button
                    key={level}
                    className={`level-btn ${level} ${scores[criterion.id] === level ? 'selected' : ''}`}
                    onClick={() => onScore(criterion.id, level)}
                  >
                    <span className="level-label">
                      {level === 'low' ? 'Not Yet' : level === 'medium' ? 'Getting There' : 'Ready'}
                    </span>
                    <span className="level-desc">{criterion.levels[level]}</span>
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function RadarChart({ dimensions, scores }: { dimensions: Dimension[]; scores: Record<string, Level> }) {
  const size = 180;
  const center = size / 2;
  const maxRadius = 70;

  const getScore = (dim: Dimension) => {
    const answered = dim.criteria.filter(c => scores[c.id] !== null).length;
    if (answered === 0) return 0;
    const avg = dim.criteria.reduce((sum, c) => {
      const s = scores[c.id];
      if (s === 'high') return sum + 3;
      if (s === 'medium') return sum + 2;
      if (s === 'low') return sum + 1;
      return sum;
    }, 0) / dim.criteria.length;
    return avg / 3;
  };

  const points = dimensions.map((dim, i) => {
    const angle = (i / dimensions.length) * Math.PI * 2 - Math.PI / 2;
    const score = getScore(dim);
    const r = score * maxRadius;
    return {
      x: center + Math.cos(angle) * r,
      y: center + Math.sin(angle) * r,
      labelX: center + Math.cos(angle) * (maxRadius + 20),
      labelY: center + Math.sin(angle) * (maxRadius + 20),
      icon: dim.icon
    };
  });

  const pathD = points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`).join(' ') + ' Z';

  return (
    <div className="radar-container">
      <svg viewBox={`0 0 ${size} ${size}`} className="radar-svg">
        {[0.33, 0.66, 1].map(scale => (
          <circle
            key={scale}
            cx={center}
            cy={center}
            r={maxRadius * scale}
            fill="none"
            stroke="#e5e7eb"
            strokeWidth="1"
          />
        ))}

        {dimensions.map((_, i) => {
          const angle = (i / dimensions.length) * Math.PI * 2 - Math.PI / 2;
          return (
            <line
              key={i}
              x1={center}
              y1={center}
              x2={center + Math.cos(angle) * maxRadius}
              y2={center + Math.sin(angle) * maxRadius}
              stroke="#e5e7eb"
              strokeWidth="1"
            />
          );
        })}

        <path
          d={pathD}
          fill="rgba(59, 130, 246, 0.2)"
          stroke="#3b82f6"
          strokeWidth="2"
        />

        {points.map((p, i) => (
          <g key={i}>
            <circle cx={p.x} cy={p.y} r="4" fill="#3b82f6" />
            <text
              x={p.labelX}
              y={p.labelY}
              textAnchor="middle"
              dominantBaseline="middle"
              fontSize="14"
            >
              {p.icon}
            </text>
          </g>
        ))}
      </svg>
    </div>
  );
}

function Summary({ dimensions, scores }: { dimensions: Dimension[]; scores: Record<string, Level> }) {
  const allCriteria = dimensions.flatMap(d => d.criteria);
  const answered = allCriteria.filter(c => scores[c.id] !== null).length;
  const total = allCriteria.length;

  const highCount = allCriteria.filter(c => scores[c.id] === 'high').length;
  const medCount = allCriteria.filter(c => scores[c.id] === 'medium').length;
  const lowCount = allCriteria.filter(c => scores[c.id] === 'low').length;

  let verdict = '';
  let verdictColor = '#6b7280';

  if (answered === total) {
    if (lowCount >= 4) {
      verdict = 'Significant gaps to address before AI adoption.';
      verdictColor = '#dc2626';
    } else if (lowCount >= 2 || medCount >= 6) {
      verdict = 'Foundation building needed. Start with a small pilot.';
      verdictColor = '#f59e0b';
    } else {
      verdict = 'Strong readiness. Proceed with focused implementation.';
      verdictColor = '#10b981';
    }
  }

  return (
    <div className="summary-panel">
      <h3>Readiness Overview</h3>
      <RadarChart dimensions={dimensions} scores={scores} />

      <div className="score-breakdown">
        <div className="sb-item ready"><span>{highCount}</span> Ready</div>
        <div className="sb-item building"><span>{medCount}</span> Building</div>
        <div className="sb-item gap"><span>{lowCount}</span> Gap</div>
      </div>

      {answered === total && (
        <div className="verdict" style={{ borderColor: verdictColor, color: verdictColor }}>
          {verdict}
        </div>
      )}

      {answered < total && (
        <div className="incomplete">
          {answered}/{total} criteria assessed. Complete all for full picture.
        </div>
      )}
    </div>
  );
}

export default function App() {
  const [scores, setScores] = useState<Record<string, Level>>(
    Object.fromEntries(
      dimensions.flatMap(d => d.criteria.map(c => [c.id, null]))
    )
  );
  const [expandedId, setExpandedId] = useState<string | null>(dimensions[0].id);

  const handleScore = (criterionId: string, level: Level) => {
    setScores(prev => ({ ...prev, [criterionId]: level }));
  };

  return (
    <div className="app">
      <div className="header">
        <h1>AI Adoption Readiness Rubric</h1>
        <p>Assess your organization across five dimensions</p>
      </div>

      <div className="main-layout">
        <div className="dimensions-list">
          {dimensions.map(dim => (
            <DimensionCard
              key={dim.id}
              dimension={dim}
              scores={scores}
              onScore={handleScore}
              isExpanded={expandedId === dim.id}
              onToggle={() => setExpandedId(expandedId === dim.id ? null : dim.id)}
            />
          ))}
        </div>
        <Summary dimensions={dimensions} scores={scores} />
      </div>

      <div className="footer-insight">
        <strong>Key insight:</strong> Successful AI adoption isn't about having the best technology—it's about having clear goals, quality data, supportive culture, adequate capacity, and realistic expectations. Most failures happen when one of these pillars is weak.
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #1e40af 0%, #3b82f6 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 1050px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.6rem;
  margin-bottom: 0.25rem;
}

.header p {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.95rem;
}

.main-layout {
  display: grid;
  grid-template-columns: 1fr 280px;
  gap: 1rem;
  margin-bottom: 1rem;
}

@media (max-width: 850px) {
  .main-layout {
    grid-template-columns: 1fr;
  }
}

.dimensions-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.dimension-card {
  background: white;
  border-radius: 0.75rem;
  border-left: 4px solid;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.dimension-card.expanded {
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.dim-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem 1rem;
  cursor: pointer;
}

.dim-header:hover {
  background: #f9fafb;
}

.dim-title {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.dim-icon {
  font-size: 1.25rem;
}

.dim-title h3 {
  font-size: 1rem;
  color: #1f2937;
}

.dim-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.avg-badge {
  font-size: 0.65rem;
  font-weight: 600;
  padding: 0.2rem 0.4rem;
  border-radius: 0.25rem;
  text-transform: uppercase;
}

.progress-text {
  font-size: 0.75rem;
  color: #9ca3af;
}

.toggle-icon {
  font-size: 1.25rem;
  color: #9ca3af;
}

.dim-body {
  padding: 0 1rem 1rem;
  border-top: 1px solid #e5e7eb;
}

.criterion {
  margin-top: 0.75rem;
}

.criterion-statement {
  font-size: 0.9rem;
  color: #374151;
  margin-bottom: 0.5rem;
  font-weight: 500;
}

.level-options {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.35rem;
}

@media (max-width: 550px) {
  .level-options {
    grid-template-columns: 1fr;
  }
}

.level-btn {
  padding: 0.5rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.5rem;
  background: white;
  cursor: pointer;
  text-align: left;
  transition: all 0.15s;
}

.level-label {
  display: block;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 0.2rem;
}

.level-desc {
  display: block;
  font-size: 0.75rem;
  line-height: 1.3;
  color: #6b7280;
}

.level-btn.low .level-label { color: #dc2626; }
.level-btn.medium .level-label { color: #f59e0b; }
.level-btn.high .level-label { color: #10b981; }

.level-btn.low:hover, .level-btn.low.selected {
  background: #fee2e2;
  border-color: #fca5a5;
}

.level-btn.medium:hover, .level-btn.medium.selected {
  background: #fef3c7;
  border-color: #fcd34d;
}

.level-btn.high:hover, .level-btn.high.selected {
  background: #d1fae5;
  border-color: #6ee7b7;
}

.summary-panel {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
  position: sticky;
  top: 1.5rem;
  height: fit-content;
}

.summary-panel h3 {
  font-size: 1rem;
  color: #1f2937;
  margin-bottom: 0.75rem;
  text-align: center;
}

.radar-container {
  display: flex;
  justify-content: center;
  margin-bottom: 0.75rem;
}

.radar-svg {
  width: 180px;
  height: 180px;
}

.score-breakdown {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.sb-item {
  font-size: 0.7rem;
  padding: 0.3rem 0.5rem;
  border-radius: 0.25rem;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.sb-item span {
  font-weight: 700;
  font-size: 0.9rem;
}

.sb-item.ready {
  background: #d1fae5;
  color: #059669;
}

.sb-item.building {
  background: #fef3c7;
  color: #b45309;
}

.sb-item.gap {
  background: #fee2e2;
  color: #dc2626;
}

.verdict {
  text-align: center;
  font-size: 0.85rem;
  font-weight: 500;
  padding: 0.75rem;
  border: 2px solid;
  border-radius: 0.5rem;
  line-height: 1.4;
}

.incomplete {
  text-align: center;
  font-size: 0.8rem;
  color: #6b7280;
  padding: 0.5rem;
  background: #f3f4f6;
  border-radius: 0.5rem;
}

.footer-insight {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 0.75rem;
  padding: 1rem;
  font-size: 0.9rem;
  color: #374151;
  line-height: 1.5;
}

.footer-insight strong {
  color: #1e40af;
}
